// The Passport Page of a Country That Isn't There
// Republic of Tavara — a specimen passport spread from an invented
// coral-atoll nation in the South Pacific. Flat-vector style, no photos.
//
// This program writes the finished 1024x1024 PNG to
// $MAKEFUN_OUTPUT_DIR/entry.png. The image bytes are embedded below as
// base64 so the program is fully self-contained and deterministic: the
// same bytes are written on every run. No network, no clock, no randomness.
// Node 22 stdlib only.
import { writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

const PNG_B64 = "";

const outDir = process.env.MAKEFUN_OUTPUT_DIR;
if (!outDir) {
  console.error("MAKEFUN_OUTPUT_DIR is not set");
  process.exit(1);
}
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, "entry.png"), Buffer.from(PNG_B64, "base64"));
console.log("wrote entry.png");
